    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(
        uint64 n,
        uint64 ts,
        uint256 bf,
        bytes32 h,
        uint64 seq,
        bytes32 bh,
        uint256 ov,
        uint256 sc
    ) public {
        uint64 numBefore = c.number(); if (__ESBMC_reverted()) return;
        uint64 tsBefore = c.timestamp(); if (__ESBMC_reverted()) return;
        uint256 bfBefore = c.basefee(); if (__ESBMC_reverted()) return;
        bytes32 hBefore = c.hash(); if (__ESBMC_reverted()) return;
        uint64 seqBefore = c.sequenceNumber(); if (__ESBMC_reverted()) return;
        bytes32 bhBefore = c.batcherHash(); if (__ESBMC_reverted()) return;
        uint256 ovBefore = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;
        uint256 scBefore = c.l1FeeScalar(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.setL1BlockValues(n, ts, bf, h, seq, bh, ov, sc); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(
            reverted &&
            c.number() == numBefore &&
            c.timestamp() == tsBefore &&
            c.basefee() == bfBefore &&
            c.hash() == hBefore &&
            c.sequenceNumber() == seqBefore &&
            c.batcherHash() == bhBefore &&
            c.l1FeeOverhead() == ovBefore &&
            c.l1FeeScalar() == scBefore
        );
    }
    receive() external payable {}
}

