pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 n, uint64 ts, uint256 bf, bytes32 h, uint64 seq, bytes32 bh, uint256 ov, uint256 sc) internal {
        uint64 numBefore;
        try c.number() returns (uint64 __r) { numBefore = __r; } catch { return; }
        uint64 tsBefore;
        try c.timestamp() returns (uint64 __r) { tsBefore = __r; } catch { return; }
        uint256 bfBefore;
        try c.basefee() returns (uint256 __r) { bfBefore = __r; } catch { return; }
        bytes32 hBefore;
        try c.hash() returns (bytes32 __r) { hBefore = __r; } catch { return; }
        uint64 seqBefore;
        try c.sequenceNumber() returns (uint64 __r) { seqBefore = __r; } catch { return; }
        bytes32 bhBefore;
        try c.batcherHash() returns (bytes32 __r) { bhBefore = __r; } catch { return; }
        uint256 ovBefore;
        try c.l1FeeOverhead() returns (uint256 __r) { ovBefore = __r; } catch { return; }
        uint256 scBefore;
        try c.l1FeeScalar() returns (uint256 __r) { scBefore = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(n, ts, bf, h, seq, bh, ov, sc) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted &&
            c.number() == numBefore &&
            c.timestamp() == tsBefore &&
            c.basefee() == bfBefore &&
            c.hash() == hBefore &&
            c.sequenceNumber() == seqBefore &&
            c.batcherHash() == bhBefore &&
            c.l1FeeOverhead() == ovBefore &&
            c.l1FeeScalar() == scBefore);
    }

    function testFuzz_run(uint64 n, uint64 ts, uint256 bf, bytes32 h, uint64 seq, bytes32 bh, uint256 ov, uint256 sc) public {
        _run(n, ts, bf, h, seq, bh, ov, sc);
    }

    receive() external payable {}
}
